class Solution {
public:
    vector<string> beforeAndAfterPuzzles(vector<string>& phrases) {
        int n = phrases.size();
        struct Item {
            string first;
            string last;
            string full;
        };
        vector<Item> items;
        for (const string& p : phrases) {
            stringstream ss(p);
            string first, last, word;
            ss >> first;
            last = first;
            while (ss >> word) last = word;
            items.push_back({first, last, p});
        }

        set<string> unique_res;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i != j && items[i].last == items[j].first) {
                    string tail = items[j].full.substr(items[j].first.size());
                    unique_res.insert(items[i].full + tail);
                }
            }
        }
        return vector<string>(unique_res.begin(), unique_res.end());
    }
};

import java.util.*;

class Solution {
    public List<String> beforeAndAfterPuzzles(String[] phrases) {
        int n = phrases.length;
        String[][] tokens = new String[n][2];
        for (int i = 0; i < n; i++) {
            String[] words = phrases[i].split(" ");
            tokens[i][0] = words[0];
            tokens[i][1] = words[words.length - 1];
        }

        Set<String> res = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && tokens[i][1].equals(tokens[j][0])) {
                    String tail = phrases[j].substring(tokens[j][0].length());
                    res.add(phrases[i] + tail);
                }
            }
        }
        return new ArrayList<>(res);
    }
}

var beforeAndAfterPuzzles = function(phrases) {
    const n = phrases.length;
    const items = phrases.map(p => {
        const words = p.split(' ');
        return { first: words[0], last: words[words.length - 1], full: p };
    });

    const res = new Set();
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (i !== j && items[i].last === items[j].first) {
                const tail = items[j].full.slice(items[j].first.length);
                res.add(items[i].full + tail);
            }
        }
    }
    return Array.from(res).sort();
};
